"""Offline case file: concrete evidence, explicit finite limits, no scripts."""
import html
import json

CSS='''
:root{--ink:#202840;--muted:#56617a;--paper:#ffffff;--ground:#edf0f8;--blue:#304db8;--red:#a02d45;--amber:#805700;--line:#d2d9ea;--mono:Consolas,ui-monospace,monospace}*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font:15px/1.6 'Segoe UI',system-ui,sans-serif}.wrap{max-width:1200px;margin:0 auto;padding:28px 32px 60px}.mast{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid var(--ink);padding-bottom:16px;gap:16px}.brand{font-weight:800;letter-spacing:.03em}.brand:before{content:'{';font:30px var(--mono);color:var(--blue);vertical-align:middle;margin-right:10px}.mono,.eyebrow{font-family:var(--mono)}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.intro{margin:34px 0 28px;max-width:800px}h1{font-size:clamp(34px,5vw,60px);line-height:1.06;letter-spacing:-.045em;margin:10px 0 18px}h2{font-size:19px;margin:0 0 12px}p{margin:8px 0 15px}.lead{font-size:16px;color:var(--muted)}.layout{display:grid;grid-template-columns:285px 1fr;gap:22px;align-items:start}.scope{background:var(--paper);border:1px solid var(--line);padding:23px}.scope-label{display:inline-block;background:#fff4d6;color:var(--amber);font:11px var(--mono);padding:4px 8px;margin-bottom:12px}.scope dl{margin:0}.scope dt{font:11px var(--mono);color:var(--muted);margin-top:18px}.scope dd{margin:3px 0 0;font-weight:600;overflow-wrap:anywhere}.scope p{font-size:12px;color:var(--muted)}.case{background:var(--paper);border:1px solid var(--line);min-width:0}.case-head{padding:18px 24px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:10px}.status{font:11px var(--mono);padding:5px 8px;color:var(--amber);background:#fff4d6}.status.counterexample{color:var(--red);background:#fbe9ee}.witness{margin:0;padding:30px;font:19px/1.75 var(--mono);background:#f7f8fd;white-space:pre-wrap;overflow-wrap:anywhere;border-bottom:1px solid var(--line);min-height:150px}.flow{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border-bottom:1px solid var(--line)}.flow>div{padding:18px 24px;background:#f2f5ff;color:var(--blue)}.flow>div:last-child{background:#fff4f6;color:var(--red)}.flow strong{display:block;font-size:18px}.flow small{font-size:11px}.body{padding:24px;min-width:0}.reason{border-left:3px solid var(--amber);padding:12px 16px;background:#fff9eb;margin-bottom:24px;font-size:13px}.findings{list-style:none;margin:0;padding:0}.findings li{padding:16px 0;border-bottom:1px solid var(--line)}.findings li:last-child{border-bottom:0}.path{display:block;font:12px var(--mono);color:var(--blue);overflow-wrap:anywhere}.findings p{font-size:13px;margin:8px 0;color:var(--muted);overflow-wrap:anywhere}summary{cursor:pointer;color:var(--blue);padding:10px 0;font-size:13px;min-height:44px}pre.details{font:11px/1.65 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6fb;padding:15px}details{border-top:1px solid var(--line);margin-top:16px}.note{font-size:12px;color:var(--muted);padding-top:16px}.footer{font:11px var(--mono);color:var(--muted);padding-top:25px}.skip{position:absolute;top:-60px;background:white;padding:12px}.skip:focus{top:10px}a:focus-visible,summary:focus-visible{outline:3px solid var(--blue);outline-offset:3px}@media(max-width:740px){.wrap{padding:20px 16px 35px}.layout{grid-template-columns:1fr}.scope{order:2}.intro{margin:25px 0}.flow strong{font-size:16px}.body,.case-head{padding:18px}.witness{padding:20px;font-size:16px}.mast .eyebrow{max-width:120px;text-align:right}.scope dl{display:grid;grid-template-columns:1fr 1fr;gap:3px 18px}.scope dt{margin-top:9px}.scope dd{margin-top:9px}}@media print{.wrap{padding:0}.layout{display:block}.scope{margin-top:15px}.skip{display:none}pre,li{break-inside:avoid}}
'''


def render_html(report):
    escape=lambda x:html.escape(str(x),quote=True)
    dump=lambda x:escape(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False))
    status=report.get('status','unknown')
    status=status if status in ('counterexample','bounded-compatible','empty-source','unknown','error') else 'unknown'
    titles={'counterexample':'One input crosses<br>the boundary.','bounded-compatible':'No counterexample.<br>Within these limits.',
            'empty-source':'Nothing to test<br>in this domain.','unknown':'No conclusion<br>is available.','error':'The check<br>could not start.'}
    d=report.get('domain') or {}
    scope=[('Container depth',d.get('max_depth','not resolved')),('Array length',d.get('max_items','not resolved')),
           ('String length',d.get('max_string','not resolved')),('Integer interval',f"{d.get('integer_min','?')} … {d.get('integer_max','?')}"),
           ('Value alphabet',d.get('alphabet','not resolved')),('Object keys',', '.join(d.get('object_keys',[])) or 'not resolved')]
    scope_html=''.join('<dt>'+escape(k)+'</dt><dd>'+escape(v)+'</dd>' for k,v in scope)
    witness=report.get('witness_json') if status=='counterexample' else None
    content=escape(witness) if witness is not None else 'No validated counterexample was produced.'
    flow=('<section class="flow"><div><small>INDEPENDENT JSONSCHEMA CHECK</small><strong>Source accepts</strong></div><div><small>AFTER JSON SERIALIZATION</small><strong>Target rejects</strong></div></section>' if status=='counterexample' else '')
    findings=''.join('<li><span class="path">schema '+escape(f.get('schema_path','') or '/')+' · instance '+escape(f.get('instance_path','') or '/')+'</span><p>'+escape(f.get('message',''))+'</p></li>' for f in report.get('failures',[]))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Schema Boundary — compatibility evidence</title><style>{CSS}</style></head><body><a class="skip" href="#case">Skip to evidence</a><main class="wrap"><header class="mast"><span class="brand">SCHEMA BOUNDARY</span><span class="eyebrow">JSON Schema / 2020-12<br>Bounded model checking</span></header>{('<p class="reason">'+escape(report['example'])+'</p>') if report.get('example') else ''}<section class="intro"><span class="eyebrow">Source minus target</span><h1>{titles[status]}</h1><p class="lead">An interface change is easier to understand with an actual input. The evidence below is tied to a precise, finite JSON domain.</p></section><div class="layout"><aside class="scope"><span class="scope-label">NOT A UNIVERSAL PROOF</span><h2>Finite domain</h2><dl>{scope_html}</dl><p>Numbers are integer-valued only. Other keys, characters, fractions and larger structures are outside this search. Increase the domain or use other validation before making broader claims.</p><details><summary>Full domain and budgets</summary><pre class="details">{dump({'domain':report.get('domain'),'limits':report.get('limits')})}</pre></details></aside><section class="case" id="case"><header class="case-head"><span class="eyebrow">Counterexample case file</span><span class="status {status}">{escape(status)}</span></header><pre class="witness">{content}</pre>{flow}<div class="body"><div class="reason">{escape(report.get('reason','No diagnostic available.'))}</div><h2>{'Where the target rejects it' if findings else 'How to interpret this result'}</h2><ul class="findings">{findings}</ul><p class="note">A missing counterexample is not evidence outside the displayed bounds. A source with no instances is reported separately; unsupported keywords and exhausted solver budgets remain unknown.</p><details><summary>Input fingerprints and validator evidence</summary><pre class="details">{dump({k:report.get(k) for k in ('hashes','engines','verification','stats')})}</pre></details></div></section></div><footer class="footer">LOCAL ANALYSIS · NO EXTERNAL REFERENCES · NO SCRIPTS OR TELEMETRY</footer></main></body></html>'''
